<?php
namespace App\Http\Controllers; use App\Models\{User,Role}; use Illuminate\Http\Request;
class UserController extends Controller {public function index(Request $r){$q=$r->string('q')->toString();$users=User::with('role')->where('role_id',2)->when($q,fn($x)=>$x->where(fn($y)=>$y->where('name','like',"%$q%")->orWhere('email','like',"%$q%")))->latest('user_id')->paginate(15)->withQueryString();return view('admin.users.index',compact('users','q'));}public function create(){return view('admin.users.form',['user'=>new User]);}public function store(Request $r){$d=$r->validate(['name'=>'required|max:100','email'=>'required|email|max:150|unique:users,email','phone'=>'nullable|max:20','password'=>'required|min:8|confirmed']);$d['role_id']=2;User::create($d);return redirect()->route('admin.users.index')->with('success','Customer created.');}public function edit(User $user){abort_unless((int)$user->role_id===2,404);return view('admin.users.form',compact('user'));}public function update(Request $r,User $user){abort_unless((int)$user->role_id===2,404);$d=$r->validate(['name'=>'required|max:100','email'=>'required|email|max:150|unique:users,email,'.$user->user_id.',user_id','phone'=>'nullable|max:20','status'=>'required|in:Active,Suspended','password'=>'nullable|min:8|confirmed']);if(!$d['password'])unset($d['password']);$user->update($d);return redirect()->route('admin.users.index')->with('success','Customer updated.');}public function destroy(User $user){abort_unless((int)$user->role_id===2,404);$user->delete();return back()->with('success','Customer deleted.');}}
